&lt;span id=&#34;cb1-33&#34;&gt;&lt;a href=&#34;#cb1-33&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        scanf&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;st&#34;&gt;&amp;quot;&lt;/span&gt;&lt;span class=&#34;sc&#34;&gt;%d&lt;/span&gt;&lt;span class=&#34;st&#34;&gt;&amp;quot;&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;amp;&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb1-34&#34;&gt;&lt;a href=&#34;#cb1-34&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        &lt;span class=&#34;cf&#34;&gt;while&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;].&lt;/span&gt;size&lt;span class=&#34;op&#34;&gt;()][&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;].&lt;/span&gt;back&lt;span class=&#34;op&#34;&gt;()]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!=&lt;/span&gt; &lt;span class=&#34;ch&#34;&gt;&amp;#39;.&amp;#39;&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb1-35&#34;&gt;&lt;a href=&#34;#cb1-35&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;].&lt;/span&gt;pop_back&lt;span class=&#34;op&#34;&gt;();&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb1-36&#34;&gt;&lt;a href=&#34;#cb1-36&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        x &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;].&lt;/span&gt;size&lt;span class=&#34;op&#34;&gt;(),&lt;/span&gt; y &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;].&lt;/span&gt;back&lt;span class=&#34;op&#34;&gt;();&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb1-37&#34;&gt;&lt;a href=&#34;#cb1-37&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        &lt;span class=&#34;cf&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(;;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb1-38&#34;&gt;&lt;a href=&#34;#cb1-38&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;].&lt;/span&gt;push_back&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;y&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt; &lt;/span&gt;
&lt;span id=&#34;cb1-39&#34;&gt;&lt;a href=&#34;#cb1-39&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            &lt;span class=&#34;cf&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;x &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;][&lt;/span&gt;y&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;ch&#34;&gt;&amp;#39;.&amp;#39;&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;++&lt;/span&gt;x&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
